CREATE TABLE `campaigns` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `room_id` bigint(20) unsigned NOT NULL,
  `name` varchar(255) NOT NULL,
  `code` varchar(64) DEFAULT NULL,
  `restaurant` varchar(255) NOT NULL,
  `creator_admin_id` bigint(20) unsigned DEFAULT NULL,
  `sponsor_name` varchar(255) DEFAULT NULL,
  `sponsor_type` varchar(255) NOT NULL DEFAULT 'none',
  `sponsor_description` text DEFAULT NULL,
  `sponsor_allocations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sponsor_allocations`)),
  `deadline` timestamp NULL DEFAULT NULL,
  `max_budget` bigint(20) unsigned DEFAULT NULL,
  `flat_price` bigint(20) unsigned DEFAULT NULL,
  `delivery_fee` bigint(20) unsigned NOT NULL DEFAULT 0,
  `discount` bigint(20) unsigned NOT NULL DEFAULT 0,
  `self_paid_price_basis` varchar(255) NOT NULL DEFAULT 'original',
  `payment_account_id` bigint(20) unsigned DEFAULT NULL,
  `description` text DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'draft',
  `started_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `ordering_locked_at` timestamp NULL DEFAULT NULL,
  `deadline_reminder_sent_for` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `campaigns_code_unique` (`code`),
  KEY `campaigns_creator_admin_id_foreign` (`creator_admin_id`),
  KEY `campaigns_payment_account_id_foreign` (`payment_account_id`),
  KEY `campaigns_room_id_status_index` (`room_id`,`status`),
  KEY `campaigns_status_index` (`status`),
  KEY `campaigns_status_deadline_index` (`status`,`deadline`),
  KEY `campaigns_room_id_created_at_index` (`room_id`,`created_at`),
  CONSTRAINT `campaigns_creator_admin_id_foreign` FOREIGN KEY (`creator_admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `campaigns_payment_account_id_foreign` FOREIGN KEY (`payment_account_id`) REFERENCES `payment_accounts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `campaigns_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
