--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `room_id` bigint(20) unsigned NOT NULL,
  `campaign_id` bigint(20) unsigned NOT NULL,
  `room_user_id` bigint(20) unsigned NOT NULL,
  `active_order_key` bigint(20) unsigned GENERATED ALWAYS AS (case when `status` in ('submitted','confirmed','ordering','ordered','delivering') then `room_user_id` else NULL end) VIRTUAL,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `placed_by_admin_id` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(64) DEFAULT NULL,
  `payment_method` varchar(255) DEFAULT NULL,
  `subtotal` bigint(20) unsigned NOT NULL,
  `delivery_amount` bigint(20) unsigned NOT NULL DEFAULT 0,
  `discount_amount` bigint(20) unsigned NOT NULL DEFAULT 0,
  `sponsor_amount` bigint(20) unsigned NOT NULL DEFAULT 0,
  `final_amount` bigint(20) unsigned NOT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'submitted',
  `payment_status` varchar(255) NOT NULL DEFAULT 'unpaid',
  `note` text DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `paid_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_code_unique` (`code`),
  UNIQUE KEY `orders_campaign_active_user_unique` (`campaign_id`,`active_order_key`),
  KEY `orders_parent_id_foreign` (`parent_id`),
  KEY `orders_campaign_id_status_index` (`campaign_id`,`status`),
  KEY `orders_room_user_id_created_at_index` (`room_user_id`,`created_at`),
  KEY `orders_room_id_created_at_index` (`room_id`,`created_at`),
  KEY `orders_status_index` (`status`),
  KEY `orders_payment_status_index` (`payment_status`),
  KEY `orders_placed_by_admin_id_foreign` (`placed_by_admin_id`),
  KEY `orders_status_created_at_index` (`status`,`created_at`),
  KEY `orders_campaign_user_status_index` (`campaign_id`,`room_user_id`,`status`),
  CONSTRAINT `orders_campaign_id_foreign` FOREIGN KEY (`campaign_id`) REFERENCES `campaigns` (`id`),
  CONSTRAINT `orders_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_placed_by_admin_id_foreign` FOREIGN KEY (`placed_by_admin_id`) REFERENCES `admins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_room_id_foreign` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`),
  CONSTRAINT `orders_room_user_id_foreign` FOREIGN KEY (`room_user_id`) REFERENCES `room_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `orders`
--

